python3 -c "
import json
with open('/app/resources/treasury_bulletin_2020_12.json') as f:
    data = json.load(f)
# Find keys related to unemployment insurance
def find_keys(obj, parent_key=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'unemployment' in k.lower():
                print(f'Key: {parent_key}.{k}')
            find_keys(v, f'{parent_key}.{k}' if parent_key else k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):  # Check first few items
            find_keys(item, parent_key)
find_keys(data)
